+import { readFileSync, writeFileSync, existsSync } from "fs";
+import { join } from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

+const STORAGE_PATH = join(".", "session-store.json");
 const store = new Map<string, Entry>();

+const saveToFile = (): void => {
+  const data = Object.fromEntries(store);
+  writeFileSync(STORAGE_PATH, JSON.stringify(data));
+};
+
+const loadFromFile = (): void => {
+  if (!existsSync(STORAGE_PATH)) return;
+  try {
+    const data = JSON.parse(readFileSync(STORAGE_PATH, "utf-8"));
+    store.clear();
+    for (const [key, entry] of Object.entries(data)) {
+      store.set(key, entry as Entry);
+    }
+  } catch {
+    // Ignore corrupted file and start fresh
+  }
+};
+
+loadFromFile();
+
 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveToFile();
 };

